import{_ as o,C as i,c as s,o as r,aj as n,G as a,w as h}from"./chunks/framework.Bfdr4H5E.js";const p="/sk/images/D-Shaped-Profile-01.webp",f="/sk/images/D-Shaped-Profile-02.webp",d="/sk/images/D-Shaped-Profile-03.webp",u="/sk/images/D-Shaped-Profile-04.webp",m="/sk/images/P-Shaped-Profile.webp",c="/sk/images/b-Shaped-Profile-01.webp",g="/sk/images/b-Shaped-Profile-02.webp",b="/sk/images/Thin-Profile.webp",T=JSON.parse('{"title":"Different Volume Profile Shapes","description":"","frontmatter":{"outline":"deep","prev":{"text":"Volume Profile","link":"/trading-with-pav/volume-profile"},"next":{"text":"Volume Profile – Trading Setups","link":"/trading-with-pav/volume-profile-trading-setups"}},"headers":[],"relativePath":"trading-with-pav/different-volume-profile-shapes.md","filePath":"trading-with-pav/different-volume-profile-shapes.md"}'),P={name:"trading-with-pav/different-volume-profile-shapes.md"};function v(w,e,y,k,S,_){const t=i("GraphComment"),l=i("ClientOnly");return r(),s("div",null,[e[0]||(e[0]=n('<h1 id="different-volume-profile-shapes" tabindex="-1">Different Volume Profile Shapes <a class="header-anchor" href="#different-volume-profile-shapes" aria-label="Permalink to &quot;Different Volume Profile Shapes&quot;">​</a></h1><p>Let explore various Different Volume Profile Shapes and what they mean.</p><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#volume-profile-shapes">Volume Profile Shapes</a><ul><li><a href="#d-shaped-profile">D-Shaped Profile</a></li><li><a href="#p-shaped-profile">P-Shaped Profile</a></li><li><a href="#b-shaped-profile">b-Shaped Profile</a></li><li><a href="#thin-profile">Thin Profile</a></li></ul></li><li><a href="#volume-profile-shapes-–-key-points">Volume Profile Shapes – Key Points</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="volume-profile-shapes" tabindex="-1">Volume Profile Shapes <a class="header-anchor" href="#volume-profile-shapes" aria-label="Permalink to &quot;Volume Profile Shapes&quot;">​</a></h2><ul><li>There are many shapes a Volume Profile histogram can print and many different stories it can tell.</li><li>However, the shapes and the stories behind them tend to repeat themselves, and in the end, it comes down to just a few basic shapes the Volume Profile can take: <ol><li>D-Shaped Profile</li><li>P-Shaped Profile</li><li>b-Shaped Profile</li><li>Thin Profile</li></ol></li></ul><h3 id="d-shaped-profile" tabindex="-1">D-Shaped Profile <a class="header-anchor" href="#d-shaped-profile" aria-label="Permalink to &quot;D-Shaped Profile&quot;">​</a></h3><ul><li>The most common and well known is the D-profile. Its shape is similar to a letter “D”.</li><li>It is formed when the market is balanced.</li><li>This means that buyers and sellers found temporary balance and neither of them is more aggressive than the other.</li><li>The price is in a rotation or in a sideways price channel.</li><li>The D-shaped profile is usually a sign of institutions accumulating their volumes i.e. getting into large positions.</li></ul><p>There are 3 significant places to be aware of.</p><ul><li>High of the D – profile</li><li>Low of the D – profile</li><li>POC (= a place with the heaviest volumes).<br> Usually close to the middle of the D-shaped profile.</li></ul><p><img src="'+p+'" alt="D-Shaped-Profile-01"></p><p>Sideways price action – 16 Dec 22 9:15 am ~ 20 Dec 22 03:25 pm</p><p><img src="'+f+'" alt="D-Shaped-Profile-02"></p><p>Volume Profile applied on Sideways</p><p><img src="'+d+'" alt="D-Shaped-Profile-03"></p><p>Volume Profile looks D – Shaped</p><p><img src="'+u+'" alt="D-Shaped-Profile-04"></p><p>High and Low of the D – Profile</p><p>As above image shows Short trades at High of the D volume and Long trades at low of the D.</p><h3 id="p-shaped-profile" tabindex="-1">P-Shaped Profile <a class="header-anchor" href="#p-shaped-profile" aria-label="Permalink to &quot;P-Shaped Profile&quot;">​</a></h3><ul><li>Its shape is similar to a letter “P”.</li><li>It is formed when there are aggressive buyers and weak sellers.</li><li>If you look at price chart you will most likely see bull candles (aggressive buyers) and then a rotation at the day’s high (weak sellers).</li><li>P-profiles can usually be seen: <ol><li>When the market is in an uptrend.</li><li>At the possible end to a downtrend. (this is not a hard rule though)</li></ol></li></ul><p><img src="'+m+'" alt="P-Shaped-Profile"></p><p>P Shaped Profile</p><p><strong>Most significant areas within P-profile are:</strong></p><ol><li>POC: good support area if the price goes up the next day(s) and then returns to this area again (pullback). <ul><li>The price doesn’t have to return to this area immediately the next day.</li><li>It can take several days before the price comes back to this POC.</li></ul></li><li>Volume cluster in the thin area of the profile: in this place, the aggression of buyers was most significant – they put heavy volumes in the market to move the price higher. <ul><li>If the price returns there as shown in above image, it is highly probable that these aggressive buyers will become aggressive again, they will defend their positions, and they will push the price higher again.</li></ul></li></ol><h3 id="b-shaped-profile" tabindex="-1">b-Shaped Profile <a class="header-anchor" href="#b-shaped-profile" aria-label="Permalink to &quot;b-Shaped Profile&quot;">​</a></h3><ul><li>Its shape is similar to a small letter “b”. (The exact opposite of P-profile.)</li><li>It is formed when there are aggressive sellers and weak buyers.</li><li>If you look at price action chart you will most likely see bear candles (aggressive sellers) and then a rotation at the day’s low (weak buyers).</li><li>b-profiles can usually be seen: <ol><li>When the market is in a downtrend.</li><li>At the possible end of an uptrend. (this is not a hard rule though).</li></ol></li></ul><p><img src="'+c+'" alt="b-Shaped-Profile-01"></p><p>b-Shaped Profile</p><p><img src="'+g+'" alt="b-Shaped-Profile-02"></p><p>b-Shaped Profile: Pullback to POC</p><p><strong>Most significant areas within b-profile are:</strong></p><ol><li>POC: good resistance area if the market goes down the next day(s) and then returns to this area again (pullback). <ul><li>The price doesn’t have to return to this area immediately the next day.</li><li>It can take several days before the price comes back to this POC.</li></ul></li><li>Volume cluster in the thin area of the profile: in this place, the aggression of sellers was most significant – they put heavy volumes in the market to move the price lower. <ul><li>If the price returns as shown in above image there it is highly probable that these aggressive sellers will become aggressive again, they will defend their positions, and they will push the price lower again.</li></ul></li></ol><h3 id="thin-profile" tabindex="-1">Thin Profile <a class="header-anchor" href="#thin-profile" aria-label="Permalink to &quot;Thin Profile&quot;">​</a></h3><ul><li>Thin profiles appear when there is a strong uptrend or a strong downtrend.</li><li>Thin profiles are thin because one side of the market is very aggressive and moves the price very quickly in one direction.</li><li>There is not much time for volume accumulation because the market is moving too fast.</li><li>For this reason, there are usually few places with smaller volume clusters but without any major volume accumulation area.</li><li>One of our trading strategies is based on trading the volume clusters.<br> Will talk more about it later in this course. <ol><li>Significant volume clusters in the uptrend (in a thin profile) are good support zones.</li><li>Significant volume clusters in the downtrend (in thin profile) are good resistance zones.</li></ol></li></ul><p><img src="'+b+'" alt="Thin-Profile"></p><p>Thin Profile: Volume Clusters</p><p><strong>Most significant places in a Thin profile are places where the price stopped moving for a while, and the Volume Profile made “volume clusters.“</strong></p><ul><li>In these volume clusters, aggressive market participants were adding to their trading positions to participate even more in the trending market.</li><li>If the price returns to these S/R zones (to the volume clusters), these aggressive participants will probably become aggressive again and add some more volumes to the market to defend their positions.</li></ul><p>This helps to move the price in the direction of the trend again.</p><h2 id="volume-profile-shapes-–-key-points" tabindex="-1">Volume Profile Shapes – Key Points <a class="header-anchor" href="#volume-profile-shapes-–-key-points" aria-label="Permalink to &quot;Volume Profile Shapes – Key Points&quot;">​</a></h2><ul><li>Not all the Volume Profile histogram shapes that you encounter will fit exactly in the description of these four basic ones showed here. Most of the time you won’t be working with the “perfectly shaped” profiles.</li><li>However, if you use your imagination a bit, then in most cases you should be able to fit every profile shape into one of these 4 basic shapes.</li><li>The first step to learning to trade with the Volume Profile is to start looking for those 4 types of profiles and trying to fit every profile you see into one of the 4 categories.</li><li>Based on this, you should try to figure out where volume-based support/resistances are.</li><li>Fastest and easiest way is to start trading volume profile with the default Daily profiles (1 day = 1 profile).</li><li>However, you can look for those 4 basic shapes on every profile regardless of the time-frame. This could be Weekly profiles, 4-hour profiles, or the Flexible Volume Profile.</li></ul><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',42)),a(l,null,{default:h(()=>[a(t)]),_:1})])}const V=o(P,[["render",v]]);export{T as __pageData,V as default};
